const LogoTextFreeClause = "Render a text-free mark: a single pictorial symbol, one composition on one plain background, containing no lettering, words, letters, numerals or typography of any kind. The brand name is set in HTML beside the logo and must never be painted into the image. This instruction overrides any earlier wording in this prompt that mentions, permits or presupposes a wordmark or any text."

const LogoTextFreeSentinel = "Render a text-free mark"

func LogoWordmarkClause(text string) string {
	return fmt.Sprintf("The only text in the image is the exact wordmark %q, spelled exactly as written, rendered once, as a single composition on one plain background; no other lettering, words or numerals anywhere. This instruction overrides any earlier wording in this prompt about text.", text)
}

// in composeBrandImagePrompt's logo branch, replacing the inline no-lettering sentence:
b.WriteString(" Flat vector mark, minimal and geometric, a single clear silhouette that stays legible at favicon size, centred on a plain background, no photographic texture, no drop shadows.")
b.WriteString(" " + LogoTextFreeClause)

isLogo, logoSignal := resolveLogoIntent(kind, inputData, params.StepConfig)
if isLogo {
	wordmarkText := logoWordmarkTextFromInputs(inputData)
	var ident logoIdentity
	if wordmarkText != "" {
		ident = loadLogoIdentity(ctx, params.DB, siteID, params.Logger)
	}
	var rejected string
	promptTemplate, negativePrompt, promptSource, rejected = applyLogoTextPolicy(
		promptTemplate, negativePrompt, promptSource, wordmarkText, ident, params.Logger)
	promptSource += "+via_" + logoSignal
	if rejected != "" {
		recordLogoPolicyNote(ctx, params.DB, siteID, "logo_wordmark_rejected", ...)
	}
} else if kind == "" {
	params.Logger.Warn("image generation with NO resolvable kind ...")
	recordLogoPolicyNote(ctx, params.DB, siteID, "image_generation_without_kind", ...)
}

func resolveLogoIntent(kind string, inputData map[string]interface{}, step models.Step) (bool, string) {
	if kind == "logo" { return true, "kind" }
	if kind != "" { return false, "" }   // a stated non-logo kind is BELIEVED
	if p, ok := inputData["purpose"].(string); ok && p == "logo" { return true, "input_purpose" }
	if spec, ok := inputData["spec"].(map[string]interface{}); ok {
		if p, ok := spec["purpose"].(string); ok && p == "logo" { return true, "spec_purpose" }
	}
	if step.Config != nil { /* purpose, kind */ }
	if n := strings.ToLower(step.Name); strings.Contains(n, "logo") { return true, "step_name" }
	return false, ""
}

