	got, neg, src := applyLogoTextPolicy(boxingPrompt, "people, faces, signature, watermark", "site_plan", "", logoIdentity{}, zap.NewNop())
	// clause appended; ORIGINAL prompt preserved verbatim (the clause overrides,
	// it does not rewrite, so the wording stays auditable in origin_prompt);
	// source tagged; negatives gain text/lettering/words
}

func TestLogoTextPolicyRejectsAWordmarkThatIsNotThisSitesName(t *testing.T) {
	ident := logoIdentity{CompanyName: "Boxing Online", Domain: "boxingonline.com"}
	got, _, src := applyLogoTextPolicy("A bold logomark.", "", "site_plan", "Farm Shield Info", ident, zap.NewNop())
	// the invented string must NOT reach the prompt; must DEGRADE to text-free, not refuse
}

func TestLogoFallbackPromptCarriesTheSharedTextRule(t *testing.T) {
	got := composeBrandImagePrompt(siteBrandFacts{Name: "Boxing Online", Domain: "boxingonline.com"}, "logo")
	if !strings.Contains(got, LogoTextFreeClause) {
		t.Fatalf("the two prompt paths have drifted, which is bugs_open/417's mechanism")
	}
}

UPDATE site_plan_imagery spi SET prompt = prompt || ' — OWNER RULING 2026-08-31 (migration 680, race tail of 670): render a text-free mark ...'
 FROM site_plans sp
 WHERE sp.id = spi.plan_id AND spi.id = 'b56182fa-...' AND spi.kind='logo'
   AND sp.is_current AND spi.locked_at IS NULL
   AND spi.prompt LIKE '%no text other than the wordmark itself%'
   AND spi.prompt NOT LIKE '%migration 6%';
GET DIAGNOSTICS v_n = ROW_COUNT;
IF v_n <> 1 THEN RAISE EXCEPTION '680: expected exactly 1 race-tail row, updated % ...', v_n; END IF;
